import{c as t,Q as o,j as n,m as s}from"./chunks/framework.BqPkuuVc.js";const r="/assets/settings-workflow.Cha_15KL.png",a="/assets/event-workflow-radios-off-time.C-TMxN3E.png",i="/assets/event-workflow-start.DJmdcGYv.png",h="/assets/event-workflow-meshO-radios.Yrgwp7RS.png",l="/assets/event-workflow-complete.bUBN6_ke.png",d="/assets/event-workflow-registry.JJEbCYZE.png",k=JSON.parse('{"title":"The event workflow","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/event-workflow.md","filePath":"user/running-the-event/event-workflow.md"}'),u={name:"user/running-the-event/event-workflow.md"};function c(g,e,f,p,w,m){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="the-event-workflow" tabindex="-1">The event workflow <a class="header-anchor" href="#the-event-workflow" aria-label="Permalink to &quot;The event workflow&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and timing operators who want the same jobs done at the start and the end of every event, without a checklist to remember.</p><p>The event workflow is a short walk through the jobs you choose, one screen after the next, shown when you start an event and when you finish it: set when the meshO Radios turn off, clear the SportIdent units, start liveresultat, turn off the meshO Radios, upload to Eventor, update the competitor registry, save a backup, push to the cloud. Each screen offers its job; you do it there, or skip it with <strong>Next</strong>.</p><p>Nothing appears until you switch steps on. All are off to begin with.</p><h2 id="the-whole-job" tabindex="-1">The whole job <a class="header-anchor" href="#the-whole-job" aria-label="Permalink to &quot;The whole job&quot;">​</a></h2><ol><li><strong>Choose the steps once</strong>, in <strong>Settings → Workflow</strong>. They apply to every event on this server.</li><li><strong>Start or finish the event as usual.</strong> When the server has started or finished it, the workflow opens with the first step switched on.</li><li><strong>Work through the screens.</strong> Do each job from its screen, or click <strong>Next</strong> to skip it. <strong>Done</strong> on the last screen, or <strong>Close</strong> at any point, ends the walk.</li></ol><p>That&#39;s it. The rest of this page says when each walk is shown and what each screen does.</p><p><img src="'+r+'" alt="Settings → Workflow: the steps for when an event starts and when it is finished, each switch with what it does under it"></p><h2 id="when-it-is-shown" tabindex="-1">When it is shown <a class="header-anchor" href="#when-it-is-shown" aria-label="Permalink to &quot;When it is shown&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Walk</th><th>Shown when</th><th>Not shown when</th></tr></thead><tbody><tr><td><strong>Event started</strong></td><td>You start an event for the first time.</td><td>You resume or restart an event that has already run: its units hold the punches made so far, and clearing them would erase that backup. A test run or a replay.</td></tr><tr><td><strong>Event finished</strong></td><td>You finish an event, or use <strong>Mark finished</strong> on an interrupted one.</td><td>You stop a test run or a replay.</td></tr></tbody></table><p>A walk with no step switched on is never shown. The walk opens only once the server has started or finished the event, so a start that was refused never asks you to clear units.</p><h2 id="running-a-walk-again-by-hand" tabindex="-1">Running a walk again by hand <a class="header-anchor" href="#running-a-walk-again-by-hand" aria-label="Permalink to &quot;Running a walk again by hand&quot;">​</a></h2><p>Skipped a step, missed a unit, or corrected a result after uploading? Open the event&#39;s status menu at the top right of its pages and choose <strong>Run start workflow…</strong> or <strong>Run finish workflow…</strong>. Each is offered only when it has a step switched on:</p><ul><li><strong>Run start workflow…</strong> — while the event is being set up or is live.</li><li><strong>Run finish workflow…</strong> — while the event is live (an interim upload or backup), once it&#39;s finished, or when it was interrupted.</li></ul><p>Neither is offered during a replay: a replay re-runs a day whose units, uploads and backups are already settled.</p><h2 id="when-the-event-starts" tabindex="-1">When the event starts <a class="header-anchor" href="#when-the-event-starts" aria-label="Permalink to &quot;When the event starts&quot;">​</a></h2><h3 id="when-the-mesho-radios-turn-off" tabindex="-1">When the meshO Radios turn off <a class="header-anchor" href="#when-the-mesho-radios-turn-off" aria-label="Permalink to &quot;When the meshO Radios turn off&quot;">​</a></h3><p>This step is only offered for an event that uses meshO Radios, and only while meshO Prime is switched on in <strong>Settings → meshO Prime Connection</strong>.</p><p>Every meshO Control powers itself off at the time you choose, so a Control nobody collects doesn&#39;t run its battery flat. Choose a time after the last runner will be in.</p><p><img src="'+a+'" alt="Event started, step 1 of 2: When the meshO Radios turn off, with the time already set, the choice of In 2 to In 12 hours, Turn off at … and Don&#39;t turn them off"></p><ol><li>Pick how far ahead: <strong>In 2 hours</strong>, <strong>4</strong>, <strong>6</strong> (already chosen), <strong>8</strong> or <strong>12</strong>.</li><li>Click <strong>Turn off at …</strong>.</li></ol><p>The time is kept with the event. Every Control the Prime hears now is sent it, and a Control switched on later, or out of range now, is sent it when the Prime next hears it. The Radios page shows each Control&#39;s time under <strong>Turns off</strong>. <strong>Don&#39;t turn them off</strong> clears the time. To change it later, use <strong>Change…</strong> above the Controls on the <a href="./connecting-prime-and-radios">Radios page</a>.</p><p><strong>What to do when:</strong></p><ul><li><strong>&quot;N Controls need firmware 4.1.0 or later to turn themselves off&quot;</strong> — they keep running. Update their firmware, or turn them off by hand (or with the finish workflow&#39;s <a href="#turn-off-the-mesho-radios">Turn off the meshO Radios</a>).</li><li><strong>&quot;N Controls are on older boards&quot;</strong> — boards before PCB v6 can&#39;t power themselves off. Collect them and switch them off.</li><li><strong>The event runs late</strong> — open <strong>Run start workflow…</strong> from the event&#39;s status menu and choose a later time.</li></ul><h3 id="clear-the-sportident-units" tabindex="-1">Clear the SportIdent units <a class="header-anchor" href="#clear-the-sportident-units" aria-label="Permalink to &quot;Clear the SportIdent units&quot;">​</a></h3><p><img src="'+i+'" alt="Event started, step 2 of 2: Clear the SportIdent units, with the SportIdent reader panel and the list of units cleared so far"></p><p>Erases the memory of each <strong>Check</strong>, <strong>Start</strong> and <strong>Finish</strong> unit, so what you read back from them later is this event&#39;s punches only. It&#39;s the same erase as <strong>Clear memory</strong> on <a href="./station-memory">Station memory</a>.</p><ol><li>Connect the SportIdent reader on this screen, if it isn&#39;t already.</li><li>Put a unit on the coupling rod and click <strong>Clear unit</strong>.</li><li>Repeat for every Check, Start and Finish unit. Each one cleared is listed under <strong>Cleared</strong>.</li></ol><p><strong>What to do when:</strong></p><ul><li><strong>&quot;The unit on the coupling rod is not a Check, Start or Finish unit&quot;</strong> — nothing was erased. A control unit&#39;s memory is the backup of who visited it, so this screen never clears one. Clear a control from <a href="./station-memory">Station memory</a> if you really mean to.</li><li><strong>&quot;Still holds N records — clear it again&quot;</strong> — the erase didn&#39;t take. Leave the unit on the rod and click <strong>Clear unit</strong> again.</li><li><strong>A unit listed twice?</strong> It isn&#39;t: clearing a unit again replaces its line.</li></ul><h3 id="start-liveresultat" tabindex="-1">Start liveresultat <a class="header-anchor" href="#start-liveresultat" aria-label="Permalink to &quot;Start liveresultat&quot;">​</a></h3><p>Turns on publishing to <a href="./publishing-live-results">liveresultat</a> for the event.</p><ul><li><strong>The event has no competition yet:</strong> click <strong>Create new…</strong> or <strong>Link existing…</strong>, the same two ways in as the event&#39;s <strong>Live results</strong> tab. The screen moves on by itself once the event is linked.</li><li><strong>Start publishing</strong> turns publishing on.</li><li><strong>Make it public</strong> lets spectators see the competition on liveresultat.</li></ul><h2 id="when-the-event-is-finished" tabindex="-1">When the event is finished <a class="header-anchor" href="#when-the-event-is-finished" aria-label="Permalink to &quot;When the event is finished&quot;">​</a></h2><p>The steps come in this order on purpose: the radios first, because they&#39;re out on the course using their batteries; then the uploads and the registry; the backup and the cloud push last, so both copies of the event carry whatever the earlier steps changed.</p><h3 id="turn-off-the-mesho-radios" tabindex="-1">Turn off the meshO Radios <a class="header-anchor" href="#turn-off-the-mesho-radios" aria-label="Permalink to &quot;Turn off the meshO Radios&quot;">​</a></h3><p>This step is only offered for an event that used meshO Radios, and only while meshO Prime is switched on in <strong>Settings → meshO Prime Connection</strong>. With Prime off, its switch is hidden on the Workflow page.</p><p><img src="'+h+'" alt="Event finished, step 1 of 5: Turn off the meshO Radios, with how many Controls were found and the Turn off radios button"></p><p>Powers off every meshO Control the Prime can hear, so the radios still out on the course stop using their batteries. It&#39;s the same <strong>Power off</strong> as on the <a href="./connecting-prime-and-radios#connecting-prime">Radios page</a>.</p><ol><li>Keep the Prime connected. The screen asks the Controls to report in, then lists how many it found.</li><li>Click <strong>Turn off N radios</strong>.</li></ol><p>A Control that&#39;s turned off can only be turned on manually.</p><p><strong>What to do when:</strong></p><ul><li><strong>&quot;An event is still running, so the radios can&#39;t be turned off yet&quot;</strong> — another event is still live and using the Prime. Finish it, then choose <strong>Run finish workflow…</strong> from this event&#39;s status menu.</li><li><strong>&quot;N Controls are on older boards and have to be switched off by hand&quot;</strong> — boards before PCB v6 can&#39;t power themselves off. Collect them and switch them off.</li><li><strong>It stays on &quot;Looking for meshO Controls…&quot;</strong> — no Control has answered. Check the Prime is plugged in and that the Controls are switched on and in range.</li><li><strong>A Control is listed under &quot;Not turned off&quot;</strong> — it didn&#39;t take the command, usually because it&#39;s out of range. Click <strong>Turn off</strong> again, or switch it off when you collect it.</li></ul><h3 id="upload-to-eventor" tabindex="-1">Upload to Eventor <a class="header-anchor" href="#upload-to-eventor" aria-label="Permalink to &quot;Upload to Eventor&quot;">​</a></h3><p>This step is only offered while Eventor is switched on in <strong>Settings → <a href="./../reference/settings#eventor">Eventor</a></strong>. With Eventor off, its switch is hidden on the Workflow page and the step is left out of the walk; switch Eventor back on and the step returns as you left it.</p><p><img src="'+l+'" alt="Event finished, step 2 of 5: Upload to Eventor, with the Upload results… button"></p><p>Click <strong>Upload results…</strong>. You choose the Eventor event and the kind of result before anything is sent, exactly as from <strong>Results → Publish → Upload to Eventor</strong>. See <a href="./../after-the-event/exports#uploading-to-eventor">Uploading to Eventor</a>.</p><p>An event with both relay and individual classes shows <strong>Upload individual results…</strong> and <strong>Upload relay results…</strong>: Eventor takes each kind in a file of its own, so upload one after the other.</p><h3 id="update-the-competitor-registry" tabindex="-1">Update the competitor registry <a class="header-anchor" href="#update-the-competitor-registry" aria-label="Permalink to &quot;Update the competitor registry&quot;">​</a></h3><p><img src="'+d+'" alt="Event finished, step 3 of 5: Update the competitor registry, listing what each person&#39;s registry entry will hold after saving, all ticked, with Save to registry"></p><p>Lists what the event will save to the <a href="./../reference/competitor-registry">competitor registry</a>: people new to it, card changes, clubs, IOF IDs and custom fields. Only what the registry stores is listed — never a class or a course. A person new to the registry shows everything they&#39;ll be added with; anything that won&#39;t be saved, such as a hire card or a club not in the club list, is struck through with the reason. Everything is ticked.</p><ol><li>Untick anything that shouldn&#39;t be saved.</li><li>Click <strong>Save to registry</strong>. Anything that wasn&#39;t saved is listed under <strong>Not saved</strong>, with the reason.</li></ol><p>The same rules apply as in the <a href="./../after-the-event/changes-report#applying-changes-to-the-competitor-registry">changes report</a>: a hire card is never saved, and a registry entry that has changed since is never overwritten. For the full report, with its exports and the option to push changes into future events, click <strong>Open the full changes report…</strong>.</p><h3 id="save-a-backup" tabindex="-1">Save a backup <a class="header-anchor" href="#save-a-backup" aria-label="Permalink to &quot;Save a backup&quot;">​</a></h3><p>Click <strong>Save backup</strong> to save a zip of the whole event on the computer running meshO Manager. The screen names the file it saved. To download a copy to this computer instead, use <strong>Back up</strong> on the event&#39;s card. See <a href="./../reference/backup-and-restore">Backup and restore</a>.</p><h3 id="push-to-the-cloud" tabindex="-1">Push to the cloud <a class="header-anchor" href="#push-to-the-cloud" aria-label="Permalink to &quot;Push to the cloud&quot;">​</a></h3><p>Click <strong>Push now</strong> to send the event to the meshO cloud, where spectators can see its results. Once it&#39;s there, <strong>Open the spectator page</strong> takes you to it.</p><ul><li><strong>&quot;Cloud sync is not set up on this computer&quot;</strong> — set it up in <strong>Settings → <a href="./../reference/settings#cloud-sync">Cloud sync</a></strong> first.</li><li>With automatic cloud sync on, a finished event is queued for the cloud anyway. Pushing here sends it now, while you&#39;re watching, rather than in the background.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../reference/settings#workflow">Settings → Workflow</a></li><li><a href="./station-memory">Station memory</a></li><li><a href="./publishing-live-results">Publishing live results online</a></li><li><a href="./../after-the-event/changes-report">Changes report</a></li><li><a href="./../after-the-event/end-of-event-checklist">End-of-event checklist</a></li><li><a href="./../event-setup/pre-event-checklist">Pre-event checklist</a></li></ul>',60)])])}const y=t(u,[["render",c]]);export{k as __pageData,y as default};
